import argparse
import json
import os
import subprocess
import requests
import threading
import queue
from concurrent.futures import ThreadPoolExecutor, as_completed

def fetch_token(credentials_path, token_url):
    with open(credentials_path, 'r') as f:
        creds = json.load(f)
    client_id = creds['client_id']
    client_secret = creds['client_secret']

    data = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }

    response = requests.post(token_url, data=data, headers={'Content-Type': 'application/x-www-form-urlencoded'})
    if response.status_code != 200:
        print('TOKEN_ERROR', file=sys.stderr)
        sys.exit(1)
    return response.json().get('access_token')

def process_command(command, token, command_queue, result_queue):
    env = os.environ.copy()
    env['API_TOKEN'] = token
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        result_queue.put(('OK', command))
    except subprocess.CalledProcessError as e:
        result_queue.put(('FAILED', command))
    except Exception as e:
        result_queue.put(('FAILED', command))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('input_file', help='Path to the file containing commands')
    parser.add_argument('--credentials', required=True, help='Path to JSON file with client_id and client_secret')
    parser.add_argument('--token-url', required=True, help='Token endpoint URL')
    args = parser.parse_args()

    token = fetch_token(args.credentials, args.token_url)

    command_queue = queue.Queue()
    result_queue = queue.Queue()

    with open(args.input_file, 'r') as f:
        commands = [line.strip() for line in f if line.strip()]

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for cmd in commands:
            command_queue.put(cmd)

        for _ in range(min(4, len(commands))):
            if not command_queue.empty():
                cmd = command_queue.get()
                futures.append(executor.submit(process_command, cmd, token, command_queue, result_queue))

        for future in as_completed(futures):
            status, cmd = future.result()
            if status == 'OK':
                print(f"{status}: {cmd}")
            else:
                print(f"{status}: {cmd}", file=sys.stderr)

    for cmd in commands:
        if not command_queue.empty():
            command_queue.get()

    if result_queue.empty():
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    import sys
    main()
